module requant (
    input  wire              clk,
    input  wire              rst_n,
    input  wire signed [28:0] acc_in,
    input  wire        [17:0] scale,
    input  wire        [6:0]  shift,
    input  wire               valid_in,
    output reg  signed [7:0]  q_out,
    output reg                sat,
    output reg                valid_out
);

    // -------------------------------------------------------------------------
    // Stage 1 – register inputs
    // -------------------------------------------------------------------------
    reg signed [28:0] s1_acc;
    reg        [17:0] s1_scale;
    reg        [6:0]  s1_shift;
    reg               s1_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s1_acc   <= 29'b0;
            s1_scale <= 18'b0;
            s1_shift <= 7'b0;
            s1_valid <= 1'b0;
        end else begin
            s1_acc   <= acc_in;
            s1_scale <= scale;
            s1_shift <= shift;
            s1_valid <= valid_in;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 2 – compute and register four partial products
    // scale is split into slices [4:0], [9:5], [14:10], [17:15]
    // pp_i = acc * slice_i placed at the correct power-of-two offset
    // -------------------------------------------------------------------------

    // Sign-extend acc to 34 bits for the five-bit slices
    wire signed [33:0] acc_ext34 = {{5{s1_acc[28]}}, s1_acc};
    wire signed [33:0] sl0_ext   = {29'b0, s1_scale[4:0]};
    wire signed [33:0] sl1_ext   = {29'b0, s1_scale[9:5]};
    wire signed [33:0] sl2_ext   = {29'b0, s1_scale[14:10]};

    // Sign-extend acc to 32 bits for the three-bit slice
    wire signed [31:0] acc_ext32 = {{3{s1_acc[28]}}, s1_acc};
    wire signed [31:0] sl3_ext   = {29'b0, s1_scale[17:15]};

    wire signed [33:0] pp0_raw = acc_ext34 * sl0_ext;
    wire signed [33:0] pp1_raw = acc_ext34 * sl1_ext;
    wire signed [33:0] pp2_raw = acc_ext34 * sl2_ext;
    wire signed [31:0] pp3_raw = acc_ext32 * sl3_ext;

    // Place each partial product in a 47-bit signed field
    wire signed [46:0] comb_pp0 = {{13{pp0_raw[33]}}, pp0_raw};
    wire signed [46:0] comb_pp1 = {{8{pp1_raw[33]}},  pp1_raw, 5'b0};
    wire signed [46:0] comb_pp2 = {{3{pp2_raw[33]}},  pp2_raw, 10'b0};
    wire signed [46:0] comb_pp3 = {pp3_raw, 15'b0};

    reg signed [46:0] s2_pp0, s2_pp1, s2_pp2, s2_pp3;
    reg        [6:0]  s2_shift;
    reg               s2_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s2_pp0   <= 47'b0;
            s2_pp1   <= 47'b0;
            s2_pp2   <= 47'b0;
            s2_pp3   <= 47'b0;
            s2_shift <= 7'b0;
            s2_valid <= 1'b0;
        end else begin
            s2_pp0   <= comb_pp0;
            s2_pp1   <= comb_pp1;
            s2_pp2   <= comb_pp2;
            s2_pp3   <= comb_pp3;
            s2_shift <= s1_shift;
            s2_valid <= s1_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 3 – sum pairs, registered (adder tree level 1)
    // -------------------------------------------------------------------------
    wire signed [47:0] comb_sum01 = {{1{s2_pp0[46]}}, s2_pp0}
                                  + {{1{s2_pp1[46]}}, s2_pp1};
    wire signed [47:0] comb_sum23 = {{1{s2_pp2[46]}}, s2_pp2}
                                  + {{1{s2_pp3[46]}}, s2_pp3};

    reg signed [47:0] s3_sum01, s3_sum23;
    reg        [6:0]  s3_shift;
    reg               s3_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s3_sum01 <= 48'b0;
            s3_sum23 <= 48'b0;
            s3_shift <= 7'b0;
            s3_valid <= 1'b0;
        end else begin
            s3_sum01 <= comb_sum01;
            s3_sum23 <= comb_sum23;
            s3_shift <= s2_shift;
            s3_valid <= s2_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 4 – full product p, registered (adder tree level 2)
    // -------------------------------------------------------------------------
    wire signed [48:0] comb_p = {{1{s3_sum01[47]}}, s3_sum01}
                               + {{1{s3_sum23[47]}}, s3_sum23};

    reg signed [48:0] s4_p;
    reg        [6:0]  s4_shift;
    reg               s4_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s4_p     <= 49'b0;
            s4_shift <= 7'b0;
            s4_valid <= 1'b0;
        end else begin
            s4_p     <= comb_p;
            s4_shift <= s3_shift;
            s4_valid <= s3_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 5 – rounding add, registered
    // round_term = 2^(shift-1) when shift > 0, else 0
    // -------------------------------------------------------------------------
    wire [48:0] round_term;
    assign round_term = (s4_shift != 7'b0) ? (49'b1 << (s4_shift - 7'b1)) : 49'b0;

    wire signed [49:0] p_rounded_comb = {{1{s4_p[48]}}, s4_p}
                                       + $signed({1'b0, round_term});

    reg signed [49:0] s5_rounded;
    reg        [6:0]  s5_shift;
    reg               s5_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s5_rounded <= 50'b0;
            s5_shift   <= 7'b0;
            s5_valid   <= 1'b0;
        end else begin
            s5_rounded <= p_rounded_comb;
            s5_shift   <= s4_shift;
            s5_valid   <= s4_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 6 – arithmetic right shift, registered
    // -------------------------------------------------------------------------
    wire signed [49:0] shifted_comb = s5_rounded >>> s5_shift;

    reg signed [49:0] s6_shifted;
    reg               s6_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s6_shifted <= 50'b0;
            s6_valid   <= 1'b0;
        end else begin
            s6_shifted <= shifted_comb;
            s6_valid   <= s5_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 7 – pipeline register (delay to reach exact 9-stage latency)
    // -------------------------------------------------------------------------
    reg signed [49:0] s7_shifted;
    reg               s7_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s7_shifted <= 50'b0;
            s7_valid   <= 1'b0;
        end else begin
            s7_shifted <= s6_shifted;
            s7_valid   <= s6_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 8 – saturation, registered
    // -------------------------------------------------------------------------
    wire sat_pos = (s7_shifted > 50'sd127);
    wire sat_neg = (s7_shifted < -50'sd128);

    reg signed [7:0] s8_q;
    reg              s8_sat;
    reg              s8_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s8_q     <= 8'b0;
            s8_sat   <= 1'b0;
            s8_valid <= 1'b0;
        end else begin
            if (sat_pos) begin
                s8_q   <= 8'sd127;
                s8_sat <= 1'b1;
            end else if (sat_neg) begin
                s8_q   <= -8'sd128;
                s8_sat <= 1'b1;
            end else begin
                s8_q   <= s7_shifted[7:0];
                s8_sat <= 1'b0;
            end
            s8_valid <= s7_valid;
        end
    end

    // -------------------------------------------------------------------------
    // Stage 9 – output register
    // -------------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            q_out     <= 8'b0;
            sat       <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            q_out     <= s8_q;
            sat       <= s8_sat;
            valid_out <= s8_valid;
        end
    end

endmodule

module requant (
    input  wire              clk,
    input  wire              rst_n,
    input  wire signed [28:0] acc_in,
    input  wire        [17:0] scale,
    input  wire        [6:0]  shift,
    input  wire               valid_in,
    output reg  signed [7:0]  q_out,
    output reg                sat,
    output reg                valid_out
);

    // Stage 1 – register inputs
    reg signed [28:0] s1_acc;
    reg        [17:0] s1_scale;
    reg        [6:0]  s1_shift;
    reg               s1_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s1_acc   <= 29'b0;
            s1_scale <= 18'b0;
            s1_shift <= 7'b0;
            s1_valid <= 1'b0;
        end else begin
            s1_acc   <= acc_in;
            s1_scale <= scale;
            s1_shift <= shift;
            s1_valid <= valid_in;
        end
    end

    // Stage 2 – compute and register four partial products
    wire signed [33:0] acc_ext34 = {{5{s1_acc[28]}}, s1_acc};
    wire signed [33:0] sl0_ext   = {29'b0, s1_scale[4:0]};
    wire signed [33:0] sl1_ext   = {29'b0, s1_scale[9:5]};
    wire signed [33:0] sl2_ext   = {29'b0, s1_scale[14:10]};
    wire signed [31:0] acc_ext32 = {{3{s1_acc[28]}}, s1_acc};
    wire signed [31:0] sl3_ext   = {29'b0, s1_scale[17:15]};

    wire signed [33:0] pp0_raw = acc_ext34 * sl0_ext;
    wire signed [33:0] pp1_raw = acc_ext34 * sl1_ext;
    wire signed [33:0] pp2_raw = acc_ext34 * sl2_ext;
    wire signed [31:0] pp3_raw = acc_ext32 * sl3_ext;

    wire signed [46:0] comb_pp0 = {{13{pp0_raw[33]}}, pp0_raw};
    wire signed [46:0] comb_pp1 = {{8{pp1_raw[33]}},  pp1_raw, 5'b0};
    wire signed [46:0] comb_pp2 = {{3{pp2_raw[33]}},  pp2_raw, 10'b0};
    wire signed [46:0] comb_pp3 = {pp3_raw, 15'b0};

    reg signed [46:0] s2_pp0, s2_pp1, s2_pp2, s2_pp3;
    reg        [6:0]  s2_shift;
    reg               s2_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s2_pp0   <= 47'b0;
            s2_pp1   <= 47'b0;
            s2_pp2   <= 47'b0;
            s2_pp3   <= 47'b0;
            s2_shift <= 7'b0;
            s2_valid <= 1'b0;
        end else begin
            s2_pp0   <= comb_pp0;
            s2_pp1   <= comb_pp1;
            s2_pp2   <= comb_pp2;
            s2_pp3   <= comb_pp3;
            s2_shift <= s1_shift;
            s2_valid <= s1_valid;
        end
    end

    // Stage 3 – sum pairs (adder tree level 1)
    wire signed [47:0] comb_sum01 = {{1{s2_pp0[46]}}, s2_pp0}
                                  + {{1{s2_pp1[46]}}, s2_pp1};
    wire signed [47:0] comb_sum23 = {{1{s2_pp2[46]}}, s2_pp2}
                                  + {{1{s2_pp3[46]}}, s2_pp3};

    reg signed [47:0] s3_sum01, s3_sum23;
    reg        [6:0]  s3_shift;
    reg               s3_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s3_sum01 <= 48'b0;
            s3_sum23 <= 48'b0;
            s3_shift <= 7'b0;
            s3_valid <= 1'b0;
        end else begin
            s3_sum01 <= comb_sum01;
            s3_sum23 <= comb_sum23;
            s3_shift <= s2_shift;
            s3_valid <= s2_valid;
        end
    end

    // Stage 4 – full product p AND round_term, both registered
    // round_term barrel-shift is isolated here; stage 5 only adds two regs
    wire signed [48:0] comb_p = {{1{s3_sum01[47]}}, s3_sum01}
                               + {{1{s3_sum23[47]}}, s3_sum23};

    wire [48:0] comb_round_term;
    assign comb_round_term = (s3_shift != 7'b0) ? (49'b1 << (s3_shift - 7'b1)) : 49'b0;

    reg signed [48:0] s4_p;
    reg        [48:0] s4_round_term;
    reg        [6:0]  s4_shift;
    reg               s4_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s4_p          <= 49'b0;
            s4_round_term <= 49'b0;
            s4_shift      <= 7'b0;
            s4_valid      <= 1'b0;
        end else begin
            s4_p          <= comb_p;
            s4_round_term <= comb_round_term;
            s4_shift      <= s3_shift;
            s4_valid      <= s3_valid;
        end
    end

    // Stage 5 – rounding add (simple addition of two registered values)
    wire signed [49:0] p_rounded_comb = {{1{s4_p[48]}}, s4_p}
                                       + $signed({1'b0, s4_round_term});

    reg signed [49:0] s5_rounded;
    reg        [6:0]  s5_shift;
    reg               s5_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s5_rounded <= 50'b0;
            s5_shift   <= 7'b0;
            s5_valid   <= 1'b0;
        end else begin
            s5_rounded <= p_rounded_comb;
            s5_shift   <= s4_shift;
            s5_valid   <= s4_valid;
        end
    end

    // Stage 6 – arithmetic right shift
    wire signed [49:0] shifted_comb = s5_rounded >>> s5_shift;

    reg signed [49:0] s6_shifted;
    reg               s6_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s6_shifted <= 50'b0;
            s6_valid   <= 1'b0;
        end else begin
            s6_shifted <= shifted_comb;
            s6_valid   <= s5_valid;
        end
    end

    // Stage 7 – delay register
    reg signed [49:0] s7_shifted;
    reg               s7_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s7_shifted <= 50'b0;
            s7_valid   <= 1'b0;
        end else begin
            s7_shifted <= s6_shifted;
            s7_valid   <= s6_valid;
        end
    end

    // Stage 8 – saturation
    wire sat_pos = (s7_shifted > 50'sd127);
    wire sat_neg = (s7_shifted < -50'sd128);

    reg signed [7:0] s8_q;
    reg              s8_sat;
    reg              s8_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s8_q     <= 8'b0;
            s8_sat   <= 1'b0;
            s8_valid <= 1'b0;
        end else begin
            if (sat_pos) begin
                s8_q   <= 8'sd127;
                s8_sat <= 1'b1;
            end else if (sat_neg) begin
                s8_q   <= -8'sd128;
                s8_sat <= 1'b1;
            end else begin
                s8_q   <= s7_shifted[7:0];
                s8_sat <= 1'b0;
            end
            s8_valid <= s7_valid;
        end
    end

    // Stage 9 – output register
    always @(posedge clk) begin
        if (!rst_n) begin
            q_out     <= 8'b0;
            sat       <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            q_out     <= s8_q;
            sat       <= s8_sat;
            valid_out <= s8_valid;
        end
    end

endmodule

module requant (
    input  wire              clk,
    input  wire              rst_n,
    input  wire signed [28:0] acc_in,
    input  wire        [17:0] scale,
    input  wire        [6:0]  shift,
    input  wire               valid_in,
    output reg  signed [7:0]  q_out,
    output reg                sat,
    output reg                valid_out
);

    // ---------------------------------------------------------------
    // Stage 1: register inputs
    // ---------------------------------------------------------------
    reg signed [28:0] s1_acc;
    reg        [17:0] s1_scale;
    reg        [6:0]  s1_shift;
    reg               s1_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s1_acc   <= 29'b0;
            s1_scale <= 18'b0;
            s1_shift <= 7'b0;
            s1_valid <= 1'b0;
        end else begin
            s1_acc   <= acc_in;
            s1_scale <= scale;
            s1_shift <= shift;
            s1_valid <= valid_in;
        end
    end

    // ---------------------------------------------------------------
    // Stage 2: partial products + round_term, all registered
    // Split scale into four slices of 5/5/5/3 bits.
    // pp_k = acc * scale[hi:lo] (unsigned slice zero-extended to signed)
    // comb_ppN already includes the positional left-shift.
    // round_term = 2^(shift-1) when shift>0, else 0.
    // ---------------------------------------------------------------
    wire signed [34:0] mul0 = s1_acc * $signed({1'b0, s1_scale[4:0]});    // 29+6 = 35b
    wire signed [34:0] mul1 = s1_acc * $signed({1'b0, s1_scale[9:5]});
    wire signed [34:0] mul2 = s1_acc * $signed({1'b0, s1_scale[14:10]});
    wire signed [32:0] mul3 = s1_acc * $signed({1'b0, s1_scale[17:15]});  // 29+4 = 33b

    // Sign-extend each product to 48 bits and apply positional shift
    wire signed [47:0] comb_pp0 = {{13{mul0[34]}}, mul0};
    wire signed [47:0] comb_pp1 = {{8{mul1[34]}},  mul1, 5'b0};
    wire signed [47:0] comb_pp2 = {{3{mul2[34]}},  mul2, 10'b0};
    wire signed [47:0] comb_pp3 = {mul3, 15'b0};

    // round_term: a single power-of-two, max 2^45, fits in 46 bits unsigned
    wire [45:0] comb_round = (s1_shift != 7'b0) ? (46'b1 << (s1_shift - 7'b1)) : 46'b0;

    reg signed [47:0] s2_pp0, s2_pp1, s2_pp2, s2_pp3;
    reg        [45:0] s2_round;
    reg        [6:0]  s2_shift;
    reg               s2_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s2_pp0  <= 48'b0; s2_pp1  <= 48'b0;
            s2_pp2  <= 48'b0; s2_pp3  <= 48'b0;
            s2_round <= 46'b0;
            s2_shift <= 7'b0; s2_valid <= 1'b0;
        end else begin
            s2_pp0  <= comb_pp0; s2_pp1  <= comb_pp1;
            s2_pp2  <= comb_pp2; s2_pp3  <= comb_pp3;
            s2_round <= comb_round;
            s2_shift <= s1_shift; s2_valid <= s1_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 3: adder-tree level 1 — two independent additions
    //   sum01  = pp0 + pp1
    //   sum23r = pp2 + pp3 + round_term   (round folded into tree here)
    // ---------------------------------------------------------------
    wire signed [48:0] comb_sum01  = {s2_pp0[47], s2_pp0} + {s2_pp1[47], s2_pp1};
    wire signed [48:0] comb_pp2_pp3 = {s2_pp2[47], s2_pp2} + {s2_pp3[47], s2_pp3};
    // round is non-negative; zero-extend to 49 bits
    wire signed [48:0] comb_sum23r = comb_pp2_pp3 + {3'b0, s2_round};

    reg signed [48:0] s3_sum01, s3_sum23r;
    reg        [6:0]  s3_shift;
    reg               s3_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s3_sum01  <= 49'b0; s3_sum23r <= 49'b0;
            s3_shift  <= 7'b0;  s3_valid  <= 1'b0;
        end else begin
            s3_sum01  <= comb_sum01; s3_sum23r <= comb_sum23r;
            s3_shift  <= s2_shift;   s3_valid  <= s2_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 4: adder-tree level 2 — final rounded product
    // ---------------------------------------------------------------
    wire signed [49:0] comb_p_rounded = {s3_sum01[48], s3_sum01}
                                      + {s3_sum23r[48], s3_sum23r};

    reg signed [49:0] s4_p_rounded;
    reg        [6:0]  s4_shift;
    reg               s4_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s4_p_rounded <= 50'b0; s4_shift <= 7'b0; s4_valid <= 1'b0;
        end else begin
            s4_p_rounded <= comb_p_rounded;
            s4_shift     <= s3_shift;
            s4_valid     <= s3_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 5: delay register (balance pipeline)
    // ---------------------------------------------------------------
    reg signed [49:0] s5_p_rounded;
    reg        [6:0]  s5_shift;
    reg               s5_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s5_p_rounded <= 50'b0; s5_shift <= 7'b0; s5_valid <= 1'b0;
        end else begin
            s5_p_rounded <= s4_p_rounded;
            s5_shift     <= s4_shift;
            s5_valid     <= s4_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 6: arithmetic right shift  (barrel shifter, 50b / 7b)
    // ---------------------------------------------------------------
    wire signed [49:0] comb_shifted = s5_p_rounded >>> s5_shift;

    reg signed [49:0] s6_shifted;
    reg               s6_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s6_shifted <= 50'b0; s6_valid <= 1'b0;
        end else begin
            s6_shifted <= comb_shifted;
            s6_valid   <= s5_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 7: delay register
    // ---------------------------------------------------------------
    reg signed [49:0] s7_shifted;
    reg               s7_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s7_shifted <= 50'b0; s7_valid <= 1'b0;
        end else begin
            s7_shifted <= s6_shifted;
            s7_valid   <= s6_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 8: saturation  [-128, 127]
    // ---------------------------------------------------------------
    wire sat_pos = (s7_shifted > 50'sd127);
    wire sat_neg = (s7_shifted < -50'sd128);

    reg signed [7:0] s8_q;
    reg              s8_sat;
    reg              s8_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s8_q <= 8'b0; s8_sat <= 1'b0; s8_valid <= 1'b0;
        end else begin
            if (sat_pos) begin
                s8_q   <= 8'sd127;
                s8_sat <= 1'b1;
            end else if (sat_neg) begin
                s8_q   <= -8'sd128;
                s8_sat <= 1'b1;
            end else begin
                s8_q   <= s7_shifted[7:0];
                s8_sat <= 1'b0;
            end
            s8_valid <= s7_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 9: output register
    // ---------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            q_out     <= 8'b0;
            sat       <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            q_out     <= s8_q;
            sat       <= s8_sat;
            valid_out <= s8_valid;
        end
    end

endmodule

