);

    // ---------------------------------------------------------------
    // Stage 1: register inputs
    // ---------------------------------------------------------------
    reg signed [28:0] s1_acc;
    reg        [17:0] s1_scale;
    reg        [6:0]  s1_shift;
    reg               s1_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s1_acc <= 29'b0; s1_scale <= 18'b0; s1_shift <= 7'b0; s1_valid <= 1'b0;
        end else begin
            s1_acc <= acc_in; s1_scale <= scale; s1_shift <= shift; s1_valid <= valid_in;
        end
    end

    // ---------------------------------------------------------------
    // Stage 1→2: partial products (combinatorial)
    // Split scale: [4:0]=5b, [9:5]=5b, [14:10]=5b, [17:15]=3b
    // Extend acc to ensure full-width product (Verilog result = max width of operands)
    // prod_k = acc * slice_k, positional shift applied when building 48-bit pp
    // ---------------------------------------------------------------
    wire signed [34:0] prod0_c = {{6{s1_acc[28]}}, s1_acc} * $signed({1'b0, s1_scale[4:0]});
    wire signed [34:0] prod1_c = {{6{s1_acc[28]}}, s1_acc} * $signed({1'b0, s1_scale[9:5]});
    wire signed [34:0] prod2_c = {{6{s1_acc[28]}}, s1_acc} * $signed({1'b0, s1_scale[14:10]});
    wire signed [32:0] prod3_c = {{4{s1_acc[28]}}, s1_acc} * $signed({1'b0, s1_scale[17:15]});

    wire signed [47:0] pp0_c = {{13{prod0_c[34]}}, prod0_c};
    wire signed [47:0] pp1_c = {{8{prod1_c[34]}},  prod1_c, 5'b0};
    wire signed [47:0] pp2_c = {{3{prod2_c[34]}},  prod2_c, 10'b0};
    wire signed [47:0] pp3_c = {prod3_c, 15'b0};

    // Round term: 2^(shift-1) when shift>0, else 0. Computed early and pipelined.
    wire [45:0] round_c = (s1_shift != 7'b0) ? (46'b1 << (s1_shift - 7'b1)) : 46'b0;

    // ---------------------------------------------------------------
    // Stage 2: register partial products and round term
    // ---------------------------------------------------------------
    reg signed [47:0] s2_pp0, s2_pp1, s2_pp2, s2_pp3;
    reg        [45:0] s2_round;
    reg        [6:0]  s2_shift;
    reg               s2_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s2_pp0 <= 48'b0; s2_pp1 <= 48'b0; s2_pp2 <= 48'b0; s2_pp3 <= 48'b0;
            s2_round <= 46'b0; s2_shift <= 7'b0; s2_valid <= 1'b0;
        end else begin
            s2_pp0 <= pp0_c; s2_pp1 <= pp1_c; s2_pp2 <= pp2_c; s2_pp3 <= pp3_c;
            s2_round <= round_c; s2_shift <= s1_shift; s2_valid <= s1_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 2→3: adder tree level 1 (two independent additions in parallel)
    // ---------------------------------------------------------------
    wire signed [48:0] sum01_c = {s2_pp0[47], s2_pp0} + {s2_pp1[47], s2_pp1};
    wire signed [48:0] sum23_c = {s2_pp2[47], s2_pp2} + {s2_pp3[47], s2_pp3};

    // ---------------------------------------------------------------
    // Stage 3: register adder tree level 1 results
    // ---------------------------------------------------------------
    reg signed [48:0] s3_sum01, s3_sum23;
    reg        [45:0] s3_round;
    reg        [6:0]  s3_shift;
    reg               s3_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s3_sum01 <= 49'b0; s3_sum23 <= 49'b0;
            s3_round <= 46'b0; s3_shift <= 7'b0; s3_valid <= 1'b0;
        end else begin
            s3_sum01 <= sum01_c; s3_sum23 <= sum23_c;
            s3_round <= s2_round; s3_shift <= s2_shift; s3_valid <= s2_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 3→4: adder tree level 2
    // ---------------------------------------------------------------
    wire signed [49:0] p_c = {s3_sum01[48], s3_sum01} + {s3_sum23[48], s3_sum23};

    // ---------------------------------------------------------------
    // Stage 4: register full product
    // ---------------------------------------------------------------
    reg signed [49:0] s4_p;
    reg        [45:0] s4_round;
    reg        [6:0]  s4_shift;
    reg               s4_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s4_p <= 50'b0; s4_round <= 46'b0; s4_shift <= 7'b0; s4_valid <= 1'b0;
        end else begin
            s4_p <= p_c; s4_round <= s3_round; s4_shift <= s3_shift; s4_valid <= s3_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 4→5: add round term (separate stage from tree to meet timing)
    // ---------------------------------------------------------------
    wire signed [50:0] p_rounded_c = {s4_p[49], s4_p} + {5'b0, s4_round};

    // ---------------------------------------------------------------
    // Stage 5: register rounded product
    // ---------------------------------------------------------------
    reg signed [50:0] s5_p_rounded;
    reg        [6:0]  s5_shift;
    reg               s5_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s5_p_rounded <= 51'b0; s5_shift <= 7'b0; s5_valid <= 1'b0;
        end else begin
            s5_p_rounded <= p_rounded_c; s5_shift <= s4_shift; s5_valid <= s4_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 5→6: arithmetic right shift
    // ---------------------------------------------------------------
    wire signed [50:0] shifted_c = s5_p_rounded >>> s5_shift;

    // ---------------------------------------------------------------
    // Stage 6: register shifted value
    // ---------------------------------------------------------------
    reg signed [50:0] s6_shifted;
    reg               s6_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s6_shifted <= 51'b0; s6_valid <= 1'b0;
        end else begin
            s6_shifted <= shifted_c; s6_valid <= s5_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 7: delay register
    // ---------------------------------------------------------------
    reg signed [50:0] s7_shifted;
    reg               s7_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s7_shifted <= 51'b0; s7_valid <= 1'b0;
        end else begin
            s7_shifted <= s6_shifted; s7_valid <= s6_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 7→8: saturation detect
    // ---------------------------------------------------------------
    wire sat_pos = (s7_shifted > 51'sd127);
    wire sat_neg = (s7_shifted < -51'sd128);

    // ---------------------------------------------------------------
    // Stage 8: register saturated output
    // ---------------------------------------------------------------
    reg signed [7:0] s8_q;
    reg              s8_sat;
    reg              s8_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            s8_q <= 8'b0; s8_sat <= 1'b0; s8_valid <= 1'b0;
        end else begin
            if (sat_pos) begin
                s8_q <= 8'sd127; s8_sat <= 1'b1;
            end else if (sat_neg) begin
                s8_q <= -8'sd128; s8_sat <= 1'b1;
            end else begin
                s8_q <= s7_shifted[7:0]; s8_sat <= 1'b0;
            end
            s8_valid <= s7_valid;
        end
    end

    // ---------------------------------------------------------------
    // Stage 9: output register
    // ---------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            q_out <= 8'b0; sat <= 1'b0; valid_out <= 1'b0;
        end else begin
            q_out <= s8_q; sat <= s8_sat; valid_out <= s8_valid;
        end
    end

endmodule

module requant (
    input  wire              clk,
    input  wire              rst_n,
    input  wire signed [28:0] acc_in,
    input  wire        [17:0] scale,
    input  wire        [6:0]  shift,
    input  wire               valid_in,
    output reg  signed [7:0]  q_out,
    output reg                sat,
    output reg                valid_out
);

    // Stage 1: latch inputs
    reg signed [28:0] s1_acc;
    reg        [17:0] s1_scale;
    reg        [6:0]  s1_shift;
    reg               s1_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s1_acc <= 0; s1_scale <= 0; s1_shift <= 0; s1_valid <= 0;
        end else begin
            s1_acc <= acc_in; s1_scale <= scale; s1_shift <= shift; s1_valid <= valid_in;
        end
    end

    // Stage 1->2: partial products; split scale into four slices
    wire signed [34:0] pp0_c = $signed(s1_acc) * $signed({1'b0, s1_scale[4:0]});
    wire signed [34:0] pp1_c = $signed(s1_acc) * $signed({1'b0, s1_scale[9:5]});
    wire signed [34:0] pp2_c = $signed(s1_acc) * $signed({1'b0, s1_scale[14:10]});
    wire signed [32:0] pp3_c = $signed(s1_acc) * $signed({1'b0, s1_scale[17:15]});

    wire signed [47:0] PP0 = {{13{pp0_c[34]}}, pp0_c};
    wire signed [47:0] PP1 = {{8{pp1_c[34]}},  pp1_c,  5'b0};
    wire signed [47:0] PP2 = {{3{pp2_c[34]}},  pp2_c, 10'b0};
    wire signed [47:0] PP3 = {pp3_c, 15'b0};

    // Stage 2: latch partial products
    reg signed [47:0] s2_pp0, s2_pp1, s2_pp2, s2_pp3;
    reg        [6:0]  s2_shift;
    reg               s2_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s2_pp0 <= 0; s2_pp1 <= 0; s2_pp2 <= 0; s2_pp3 <= 0;
            s2_shift <= 0; s2_valid <= 0;
        end else begin
            s2_pp0 <= PP0; s2_pp1 <= PP1; s2_pp2 <= PP2; s2_pp3 <= PP3;
            s2_shift <= s1_shift; s2_valid <= s1_valid;
        end
    end

    // Stage 2->3: adder tree level 1
    wire signed [48:0] sum01_c = {s2_pp0[47], s2_pp0} + {s2_pp1[47], s2_pp1};
    wire signed [48:0] sum23_c = {s2_pp2[47], s2_pp2} + {s2_pp3[47], s2_pp3};

    // Stage 3: latch level-1 sums
    reg signed [48:0] s3_sum01, s3_sum23;
    reg        [6:0]  s3_shift;
    reg               s3_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s3_sum01 <= 0; s3_sum23 <= 0; s3_shift <= 0; s3_valid <= 0;
        end else begin
            s3_sum01 <= sum01_c; s3_sum23 <= sum23_c;
            s3_shift <= s2_shift; s3_valid <= s2_valid;
        end
    end

    // Stage 3->4: final sum = full product p
    wire signed [49:0] p_c = {s3_sum01[48], s3_sum01} + {s3_sum23[48], s3_sum23};

    // Stage 4: latch full product
    reg signed [49:0] s4_p;
    reg        [6:0]  s4_shift;
    reg               s4_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s4_p <= 0; s4_shift <= 0; s4_valid <= 0;
        end else begin
            s4_p <= p_c; s4_shift <= s3_shift; s4_valid <= s3_valid;
        end
    end

    // Stage 4->5: shift by lower 4 bits (0-15 positions); save low 16 bits for round-bit extraction
    wire [3:0]         sh_lo4   = s4_shift[3:0];
    wire signed [49:0] temp_c   = s4_p >>> sh_lo4;
    wire        [15:0] p_low_c  = s4_p[15:0];

    // Stage 5: latch temp, p_low, sh_hi, sh_lo
    reg signed [49:0] s5_temp;
    reg        [15:0] s5_p_low;
    reg        [2:0]  s5_sh_hi;
    reg        [3:0]  s5_sh_lo;
    reg               s5_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s5_temp <= 0; s5_p_low <= 0; s5_sh_hi <= 0; s5_sh_lo <= 0; s5_valid <= 0;
        end else begin
            s5_temp  <= temp_c;
            s5_p_low <= p_low_c;
            s5_sh_hi <= s4_shift[6:4];
            s5_sh_lo <= s4_shift[3:0];
            s5_valid <= s4_valid;
        end
    end

    // Stage 5->6: high shift (0, 16, or 32 positions) + round-bit extraction
    // Use round-bit approach: extract p[shift-1] to avoid wide addition to full product
    reg signed [49:0] shifted6_c;
    always @(*) begin
        case (s5_sh_hi)
            3'd0:    shifted6_c = s5_temp;
            3'd1:    shifted6_c = s5_temp >>> 16;
            3'd2:    shifted6_c = s5_temp >>> 32;
            default: shifted6_c = s5_temp >>> 32;
        endcase
    end

    // sh_hi=0: round bit is p[sh_lo-1] = p_low[sh_lo-1]; extract via small shift
    // sh_hi=1: round bit is temp[15] (= p[15+sh_lo] = p[shift-1])
    // sh_hi=2: round bit is temp[31] (= p[31+sh_lo] = p[shift-1])
    wire [15:0] p_low_rb     = s5_p_low >> (s5_sh_lo - 4'd1);  // underflows to >>15 when sh_lo=0, guarded below
    wire        round_lo     = (s5_sh_lo != 4'd0) ? p_low_rb[0] : 1'b0;
    wire        round_bit_c  = (s5_sh_hi == 3'd0) ? round_lo :
                               (s5_sh_hi == 3'd1) ? s5_temp[15] : s5_temp[31];

    // Stage 6: latch shifted value and round bit
    reg signed [49:0] s6_shifted;
    reg               s6_round_bit;
    reg               s6_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s6_shifted <= 0; s6_round_bit <= 0; s6_valid <= 0;
        end else begin
            s6_shifted   <= shifted6_c;
            s6_round_bit <= round_bit_c;
            s6_valid     <= s5_valid;
        end
    end

    // Stage 6->7: add round bit (0 or 1 only, fast increment) + saturate
    wire signed [49:0] r_c      = s6_shifted + {{49{1'b0}}, s6_round_bit};
    wire               sat_pos_c = (r_c > 50'sd127);
    wire               sat_neg_c = (r_c < -50'sd128);

    // Stage 7: latch saturated result
    reg signed [7:0] s7_q;
    reg              s7_sat;
    reg              s7_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s7_q <= 0; s7_sat <= 0; s7_valid <= 0;
        end else begin
            if (sat_pos_c)      begin s7_q <= 8'sb01111111; s7_sat <= 1'b1; end
            else if (sat_neg_c) begin s7_q <= 8'sb10000000; s7_sat <= 1'b1; end
            else                begin s7_q <= r_c[7:0];     s7_sat <= 1'b0; end
            s7_valid <= s6_valid;
        end
    end

    // Stage 8: delay register
    reg signed [7:0] s8_q;
    reg              s8_sat;
    reg              s8_valid;
    always @(posedge clk) begin
        if (!rst_n) begin
            s8_q <= 0; s8_sat <= 0; s8_valid <= 0;
        end else begin
            s8_q <= s7_q; s8_sat <= s7_sat; s8_valid <= s7_valid;
        end
    end

    // Stage 9: output registers
    always @(posedge clk) begin
        if (!rst_n) begin
            q_out <= 0; sat <= 0; valid_out <= 0;
        end else begin
            q_out <= s8_q; sat <= s8_sat; valid_out <= s8_valid;
        end
    end

endmodule
